							"text": "Later, a conversation may be useful if the other person wants one. Name your action accurately: “I continued after you pulled away. I should have stopped.” Listen without correcting their feelings. An apology becomes more meaningful when behaviour changes, including respecting requests for distance. A good intention does not cancel an impact. Equally, this course cannot determine the legal meaning of a specific event.",
							"sourceIds": []
