							"text": "Anatomical language helps people describe a symptom, ask a question or communicate a boundary. These words are tools, not tests of gender or experience. You may use different words for your own body. In a healthcare conversation, pairing your preferred term with a familiar anatomical term can help a clinician understand you accurately.",
							"sourceIds": []
