							"text": "The penis includes the shaft and glans. The scrotum is the skin sac containing the testes, which produce sperm and hormones. The prostate and other glands contribute fluid to semen. The urethra carries urine from the bladder and, in a penis, also carries semen at a different time. [A11] Reproductive functions, urinary functions and pleasurable sensations are related in some structures but are not interchangeable concepts.",
							"sourceIds": ["A11"]
