							"text": "These descriptions outline common arrangements. They do not mean that every person has every listed organ. Bodies can differ because of innate variations, surgery, injury or other circumstances. Intersex refers to variations in sex characteristics; it does not identify a person's gender or sexual orientation. NSW Health recommends language that respects both bodily diversity and the person's own preferences. [A13]",
							"sourceIds": ["A13"]
