							"text": "Safer sex is a shared planning process. Start with the activities being considered, the body parts involved, relevant health information and each person's boundaries. An orientation or relationship label is not a substitute for that conversation. Nobody's appearance establishes their STI status, and a prevention discussion should describe practical information without labelling people as clean or dirty.",
							"sourceIds": []
