							"type": "paragraph",
							"text": "Different infections spread through different kinds of contact. Barriers can reduce exposure during vaginal, anal or oral sexual activity, but they do not remove every risk, including contact with uncovered skin. Australia's STI prevention guidance recommends combining barriers, testing, communication and appropriate vaccination. It also explains that hormonal contraception does not prevent STIs. [A23]",
