							"text": "Many STIs do not produce noticeable symptoms. Testing can identify infections that a person would otherwise miss. The Australian Government recommends discussing test frequency and relevant risk factors with a healthcare professional rather than relying on appearance or relationship status. A consultation may involve urine, blood or swab samples depending on what needs checking. [A25]",
							"sourceIds": ["A25"]
