							"text": "Tell the clinician the information needed to choose appropriate tests: relevant sexual contact, any symptoms, the timing of possible exposure and known partner diagnoses. You can describe activities and body parts without first selecting an identity label. Ask which infections and sites are being tested. A request for “everything” should lead to a clarifying conversation, not an assumption that one sample can answer every question.",
