							"text": "Timing matters. A window period is the time after infection during which a particular test may not yet detect it. Different infections and tests have different windows. For example, NSW Health's MyTest information explains that a particular HIV self-test may miss recent infection during its window period. [A26] A clinician can advise when to test now, when to repeat a test, and whether immediate preventive care is relevant. Do not wait for a window period to finish before seeking advice about symptoms or a recent exposure.",
							"sourceIds": ["A26"]
