							"type": "paragraph",
							"text": "A positive result is a health matter. Follow the clinician's advice about treatment, sexual contact, retesting and notifying relevant partners. Ask about assisted notification if direct contact is difficult or unsafe. Testing services handle health information confidentially, but some infections involve public-health notification; ask how privacy works in your situation. [A25]",
							"sourceIds": ["A25"]
