							"text": "Care continues after an interaction and during changes to a relationship. It begins with asking rather than assuming. One person may want a conversation, another may want ordinary company, and another may prefer privacy. “Would you like company, practical help or space?” offers choices. The answer can change, and offering care does not create permission for touch or access.",
							"sourceIds": []
