							"type": "paragraph",
							"text": "Repair requires accountability. If you broke an agreement, name the action, communicate any information relevant to the other person's health or choices, and follow through on practical changes. Listen to the impact without making the conversation about obtaining reassurance. An apology can be offered; forgiveness, continued contact and renewed intimacy cannot be collected as payment for it.",
							"sourceIds": []
