							"text": "Privacy obligations do not disappear at a breakup. Do not share intimate images, private diagnoses or identifying stories to recruit an audience against the other person. eSafety explains that sharing or threatening to share intimate images without consent is image-based abuse, including after a relationship ends. [A08]",
