							"text": "Supported decision-making means helping a person understand options and communicate their own choice. It does not mean obtaining a support worker's or family member's approval in place of that adult's agreement. Consent and legal capacity questions can be context-specific; this course cannot assess an individual's capacity or authorise someone else to decide for them. If understanding or voluntariness remains uncertain, do not proceed. Seek appropriate specialist advice while continuing to treat the person respectfully.",
							"sourceIds": []
