							"id": "C09-L03-P04",
							"type": "paragraph",
							"text": "Aftercare means checking what support, space or follow-up someone wants after an experience. It might be a calm conversation, privacy or practical help, and preferences can differ. Ask rather than prescribing comfort. Someone who wants to leave should be able to leave. Do not insist on touch, emotional disclosure or reassurance as a condition of care.",
							"sourceIds": []
