							"type": "paragraph",
							"text": "Aftercare cannot turn a consent violation into a consensual event. If a limit was crossed, stop, attend to immediate needs, acknowledge what happened and respect the person's choices about contact and support. Seek professional assistance for injury or distress; do not frame symptoms as proof that an experience was successful. The learning goal is reliable judgment: knowing when to pause, refuse, get help or accept accountability is more valuable than collecting experiences.",
