							"text": "Practical evidence can include account names, dates, message details and links. Do not redistribute intimate material to classmates or friends to ask what they think. Keep any record private and follow the reporting service's instructions. Reporting options differ by the situation; eSafety can assess reports of image-based abuse and provides information on other appropriate services. [B25] A course moderator is not an emergency responder or an investigative authority.",
