							"text": "If a friend is targeted, begin with, “I am glad you told me. This is not your fault. What would help right now?” Help them find the official reporting route if they want assistance. Do not demand to see the image, contact the person making threats, or announce the problem publicly. Good support gives the person more control rather than creating another audience for the abuse.",
							"sourceIds": []
