							"type": "paragraph",
							"text": "After the immediate problem, consider an account-security review using trusted guidance. Check access, passwords and recovery details on a device the person considers safe. Recovery may take time, and shame can make asking for help harder. A previous choice to flirt, send a photo or trust someone does not make another person's blackmail acceptable. The offender is responsible for the threat.",
							"sourceIds": []
