							"id": "C12-L01-P01",
							"type": "paragraph",
							"text": "A useful plan makes everyday decisions easier. It should not become a checklist of experiences you ought to have. Start with the life you want your choices to support: privacy, connection, independence, pleasure, health, rest or confidence. You can value several things at once. You can also decide that learning is enough for now and make no change to your sexual life.",
							"sourceIds": []
