							"text": "Decide what information you want to record. You do not need a diary of sexual activity, partner names, fantasies or medical history to benefit from this course. A paper note you keep private may be enough; no upload is needed. Think about who can access any device or document before saving sensitive details. You can use a fictional plan instead of recording personal information.",
							"sourceIds": []
