							"type": "paragraph",
							"text": "Review progress through choices: Can I pause when unsure? Can I hear a no without punishing it? Do I know where to ask a health question? Can I distinguish a feeling from permission to act? Course completion shows engagement with learning tasks; it does not certify someone as a safe partner or authorise another person's consent. The plan belongs to you and can be changed, paused or discarded as your circumstances change.",
							"sourceIds": []
