							"text": "When a boundary is crossed, focus on the action and its impact. Stop the behaviour. Check immediate needs without insisting on contact. Listen to the person's account without using your intentions as a defence. A useful acknowledgement names what you did: “I shared information you wanted private. I understand that was not mine to share.” Avoid apologies that shift responsibility, such as blaming the other person for not explaining perfectly.",
							"sourceIds": []
