							"text": "Offer a concrete corrective step within your control and respect the answer. You might stop contacting someone, remove material you control, or seek independent help to change your own behaviour. Do not promise a result you cannot guarantee, such as deleting every copy someone else holds. An offer of repair is not a bargain for forgiveness, renewed access or reassurance. The affected person can decline further discussion.",
