				"moduleId": "E02",
				"order": 1,
				"sections": [
					{
						"id": "E02-L01-P01",
						"type": "paragraph",
						"text": "Words such as “sex”, “foreplay” and “going further” can mean different things to different people. Naming the proposed activity helps someone understand what they are choosing. Oral contact means contact involving the mouth; genital contact can involve external touch or penetration. These categories describe activities, not a person’s orientation, experience or preferred role.",
						"sourceIds": []
					},
					{
						"id": "E02-L01-P02",
						"type": "paragraph",
						"text": "Ask about the contact someone wants, areas they want avoided and how they prefer to communicate changes. Agreement to kissing or external touch does not automatically include oral contact, penetration or contact with another body area. The right to stop applies throughout. Nobody needs to explain a boundary in enough detail to satisfy someone else. [R02]",
						"sourceIds": ["R02"]
					},
					{
						"id": "E02-L01-P03",
						"type": "paragraph",
						"text": "Health planning should match the activity. STIs can be transmitted through oral, vaginal or anal contact, and some through skin contact in areas a barrier does not cover. Condoms and dams can reduce risk when used correctly; a lack of visible symptoms does not establish that an infection is absent. A sexual health professional can advise which tests and body sites are relevant to the contact you have had. [R09]",
						"sourceIds": ["R09"]
					},
					{
						"id": "E02-L01-P04",
						"type": "paragraph",
						"text": "A useful conversation might ask: “What protection would help us feel comfortable?”, “Is there anything we should discuss before deciding?” and “What should we do if the barrier fails?” The conversation can happen before intimacy, when neither person feels rushed. You do not need to inspect another person’s medical records or demand a photograph of a test result as a condition of treating them respectfully.",
						"sourceIds": []
					},
					{
						"id": "E02-L01-P05",
						"type": "paragraph",
						"text": "Comfort also matters. Lubrication, pace, position and the choice to avoid penetration can be discussed without a performance target. If something hurts, pause or stop; recurring pain deserves assessment rather than pressure to push through. [R15] No activity in this lesson is a required milestone. Understanding the options and deciding against an activity are both valid learning outcomes.",
						"sourceIds": ["R15"]
					}
				],
				"reflection": {
					"prompt": "Write a fictional pre-intimacy conversation covering the proposed activity, one boundary, one health question and a pause option. Keep it clinical and do not describe personal encounters.",
					"optional": true,
					"persistence": "none",
					"fictionalExamplesAllowed": true,
					"countsForCertificate": false
				},
				"scenarioId": "E02-L01-SCENARIO",
				"assessmentId": "E02-L01-CHECK",
