	glossary: [
		{
			"id": "G01",
			"term": "Consent",
			"definition": "A voluntary, informed and ongoing agreement to a specific activity; legal definitions depend on jurisdiction."
		},
		{
			"id": "G02",
			"term": "Boundary",
			"definition": "A limit a person sets around their own participation, body, time, privacy or circumstances."
		},
		{
			"id": "G03",
			"term": "Desire",
			"definition": "Interest in a sexual experience; it can vary by person, situation and time."
		},
		{
			"id": "G04",
			"term": "Arousal",
			"definition": "A subjective or bodily response that is distinct from consent."
		},
		{
			"id": "G05",
			"term": "Pleasure",
			"definition": "An enjoyable experience; it is personal and is not measured only by orgasm."
		},
		{
			"id": "G06",
			"term": "Vulva",
			"definition": "The external genital structures, including the labia and the visible part of the clitoris."
		},
		{
			"id": "G07",
			"term": "Vagina",
			"definition": "An internal muscular canal; it is not the name for all external genital structures."
		},
		{
			"id": "G08",
			"term": "STI",
			"definition": "Sexually transmitted infection; a person can have an infection without obvious symptoms."
		},
		{
			"id": "G09",
			"term": "Barrier",
			"definition": "A product such as a condom or dam used to reduce contact that may transmit infection; protection is not absolute."
		},
		{
			"id": "G10",
			"term": "Contraception",
			"definition": "Methods intended to prevent pregnancy; most do not protect against STIs."
		},
		{
			"id": "G11",
			"term": "PrEP",
			"definition": "Pre-exposure prophylaxis: prescribed medicine used to reduce HIV risk before exposure; individual suitability needs clinical assessment."
		},
		{
			"id": "G12",
			"term": "PEP",
			"definition": "Post-exposure prophylaxis: urgent medicine after a possible HIV exposure; seek prompt clinical assessment."
		},
		{
			"id": "G13",
			"term": "AAC",
			"definition": "Augmentative and alternative communication, including tools and methods that support or replace speech."
		},
		{
			"id": "G14",
			"term": "Asexuality",
			"definition": "An orientation generally involving little or no sexual attraction; experience and preferred relationships vary."
		},
		{
			"id": "G15",
			"term": "Intersex",
			"definition": "An umbrella term for innate variations in sex characteristics; it does not establish a person's gender or orientation."
		},
		{
			"id": "G16",
			"term": "Gender identity",
			"definition": "A person's sense of their gender, which does not determine anatomy or sexual preferences."
		},
		{
			"id": "G17",
			"term": "Consensual nonmonogamy",
			"definition": "Relationship arrangements that may include more than one romantic or sexual connection with informed agreement."
		},
		{
			"id": "G18",
			"term": "Kink",
			"definition": "An umbrella term people use for a range of interests or practices; a label never replaces specific consent."
		},
		{
			"id": "G19",
			"term": "Aftercare",
			"definition": "Practical or emotional care agreed after an experience; it cannot retrospectively create consent."
		},
		{
			"id": "G20",
			"term": "Image-based abuse",
			"definition": "Sharing or threatening to share an intimate image or video without consent, including relevant digitally altered material."
		},
		{
			"id": "G21",
			"term": "Trauma-informed approach",
			"definition": "An approach that prioritises choice, control and sensitivity to possible distress without requiring disclosure or providing trauma treatment."
		},
		{
			"id": "G22",
			"term": "Sexual wellbeing",
			"definition": "A broad view of sexual health that includes physical, emotional and social experiences and the ability to make informed choices."
		}
	],
