async function createDemo(sql, ownerUserId, request) {
	const stamp = nowIso();
	const expiresAt = new Date(Date.now() + 72e5).toISOString();
	const token = Array.from(crypto.getRandomValues(/* @__PURE__ */ new Uint8Array(32)), (value) => value.toString(16).padStart(2, "0")).join("");
	const demoUserId = `demo:${crypto.randomUUID()}`;
	const existing = await sql.query("select demo_user_id as \"demoUserId\" from demo_sessions where owner_user_id = $1", [ownerUserId]);
	await sql.query("delete from demo_sessions where owner_user_id = $1", [ownerUserId]);
	for (const row of existing) await sql.query("delete from profiles where user_id = $1", [row.demoUserId]);
	await sql.query(`insert into profiles (user_id, display_name, weekly_goal, accepted_version, adult_confirmed_at, education_acknowledged_at, orientation_completed_at, created_at, updated_at)
     values ($1, 'Alex · demo learner', 3, $2, $3, $3, $3, $3, $3)`, [
		demoUserId,
		POLICY_VERSION,
		stamp
	]);
	await sql.query("insert into demo_sessions (token_hash, owner_user_id, demo_user_id, created_at, expires_at) values ($1, $2, $3, $4, $5)", [
		await sha256(token),
		ownerUserId,
		demoUserId,
		stamp,
		expiresAt
	]);
	await sql.query("insert into entitlements (user_id, key, source_id, expires_at, active, updated_at) values ($1, 'plus', 'isolated-demo', $2, true, $3)", [
		demoUserId,
		expiresAt,
		stamp
	]);
	const sample = modules.filter((module) => module.id === "C01" || module.id === "C02").flatMap((module) => module.lessons);
	for (const lesson of sample) await sql.query("insert into lesson_progress (user_id, lesson_id, completed_at) values ($1, $2, $3) on conflict do nothing", [
		demoUserId,
		lesson.id,
		stamp
	]);
	const check = getAssessment("C01-TEST");
	await sql.query("insert into assessment_results (user_id, assessment_id, best_score, total, passed_at, last_attempt_at) values ($1, $2, $3, $4, $5, $5)", [
		demoUserId,
		check.id,
		check.questionIds.length,
		check.questionIds.length,
		stamp
	]);
	const response = json({
		started: true,
		redirectTo: "/dashboard",
		demo: {
			active: true,
			expiresAt,
			source: "isolated-demo",
			tier: "plus"
		}
	});
	response.headers.set("set-cookie", demoCookie(token, request));
	return response;
}
